(n, k) = map(int, input().split())
s = list(input())
cnt = 0
for i in range(n - 1):
	if cnt == k:
		break
	if s[i] == '4' and s[i + 1] == '7':
		if i & 1:
			if s[i - 1] == '4':
				if cnt - k & 1:
					s[i] = '7'
				print(''.join(s))
				exit()
			s[i] = '7'
		else:
			if i != n - 2:
				if s[i + 2] == '7':
					if cnt - k & 1:
						s[i + 1] = '4'
					print(''.join(s))
					exit()
			s[i + 1] = '4'
		cnt += 1
print(''.join(s))
